def get_skyline(buildings):
    xs = sorted({b[0] for b in buildings} | {b[1] for b in buildings})
    result = []
    prev_height = 0
    for x in xs:
        max_height = 0
        for left, right, height in buildings:                # scan every building directly
            if left <= x < right:
                max_height = max(max_height, height)
        if max_height != prev_height:
            result.append([x, max_height])
            prev_height = max_height
    return result

