    static List<int[]> getSkyline(int[][] buildings) {
        TreeSet<Integer> xsSet = new TreeSet<>();
        for (int[] b : buildings) { xsSet.add(b[0]); xsSet.add(b[1]); }
        List<int[]> result = new ArrayList<>();
        int prevHeight = 0;
        for (int x : xsSet) {
            int maxHeight = 0;
            for (int[] b : buildings) {                            // scan every building directly
                if (b[0] <= x && x < b[1]) maxHeight = Math.max(maxHeight, b[2]);
            }
            if (maxHeight != prevHeight) {
                result.add(new int[]{x, maxHeight});
                prevHeight = maxHeight;
            }
        }
        return result;
    }
