import heapq

def get_skyline(buildings):
    events = []
    for left, right, height in buildings:
        events.append((left, -height, right))       # start: negative height sorts tall buildings first
        events.append((right, 0, 0))                  # end marker
    events.sort()

    result = []
    active = [(0, float('inf'))]               # (height, end) - a sentinel ground-level building
    for x, neg_h, r in events:
        while active[0][1] <= x:
            heapq.heappop(active)                       # lazily discard buildings that have ended
        if neg_h < 0:
            heapq.heappush(active, (neg_h, r))
        cur_max = -active[0][0]
        if not result or result[-1][1] != cur_max:
            result.append([x, cur_max])
    return result

