import java.util.*;

public class Main {
    static List<int[]> getSkyline(int[][] buildings) {
        List<int[]> events = new ArrayList<>();
        for (int[] b : buildings) {
            events.add(new int[]{b[0], -b[2], b[1]});    // start: negative height sorts tall buildings first
            events.add(new int[]{b[1], 0, 0});             // end marker
        }
        events.sort((a, c) -> a[0] != c[0] ? a[0] - c[0] : a[1] - c[1]);

        List<int[]> result = new ArrayList<>();
        PriorityQueue<int[]> active = new PriorityQueue<>((a, c) -> a[0] - c[0]);  // min by negative height = max height
        active.offer(new int[]{0, Integer.MAX_VALUE});
        for (int[] e : events) {
            while (active.peek()[1] <= e[0]) active.poll();     // lazily discard ended buildings
            if (e[1] < 0) active.offer(new int[]{e[1], e[2]});
            int curMax = -active.peek()[0];
            if (result.isEmpty() || result.get(result.size() - 1)[1] != curMax) {
                result.add(new int[]{e[0], curMax});
            }
        }
        return result;
    }
}

