#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> getSkyline(vector<vector<int>>& buildings) {
    // Encode start as (x, -height) and end as (x, height): sorting ascending
    // then puts starts (negative) before ends (positive) at the same x, and
    // among starts, the tallest building first.
    vector<pair<int,int>> events;
    for (auto& b : buildings) {
        events.push_back({b[0], -b[2]});   // start
        events.push_back({b[1], b[2]});     // end
    }
    sort(events.begin(), events.end());

    vector<vector<int>> result;
    multiset<int, greater<int>> active = {0};   // sentinel ground level, sorted descending
    for (auto& [x, h] : events) {
        if (h < 0) {
            active.insert(-h);                          // start: add this building's height
        } else {
            active.erase(active.find(h));                // end: remove exactly this building's height
        }
        int curMax = *active.begin();
        if (result.empty() || result.back()[1] != curMax) {
            result.push_back({x, curMax});
        }
    }
    return result;
}
